                    ["fallback"] = "Ready up. We're not running from this.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "We take the fight to them. Stay sharp.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "Line them up. We can win this.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "No backing down. We push through.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "We hold here and eliminate the threat.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "I'm ready. Let's make every strike count.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.neutral.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
            ["terse"] = {
                {
                    ["fallback"] = "Stand and fight.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.01",
                    ["phraseID"] = "terse.01",
                },
                {
                    ["fallback"] = "We take them.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.02",
                    ["phraseID"] = "terse.02",
                },
                {
                    ["fallback"] = "No retreat.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.03",
                    ["phraseID"] = "terse.03",
                },
                {
                    ["fallback"] = "Draw weapons.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.04",
                    ["phraseID"] = "terse.04",
                },
                {
                    ["fallback"] = "Kill them all.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.05",
                    ["phraseID"] = "terse.05",
                },
                {
                    ["fallback"] = "Fight through.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.06",
                    ["phraseID"] = "terse.06",
                },
                {
                    ["fallback"] = "Ready.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.07",
                    ["phraseID"] = "terse.07",
                },
                {
                    ["fallback"] = "Holding ground.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.08",
                    ["phraseID"] = "terse.08",
                },
                {
                    ["fallback"] = "Let's do this.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.09",
                    ["phraseID"] = "terse.09",
                },
                {
                    ["fallback"] = "Bring them on.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.terse.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.terse.10",
                    ["phraseID"] = "terse.10",
                },
            },
            ["warm"] = {
                {
                    ["fallback"] = "I'm with you. We can take them.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.01",
                    ["phraseID"] = "warm.01",
                },
                {
                    ["fallback"] = "Together, nothing can stop us! Let's do this.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.02",
                    ["phraseID"] = "warm.02",
                },
                {
                    ["fallback"] = "I've got your back, friend. We fight as one.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.03",
                    ["phraseID"] = "warm.03",
                },
                {
                    ["fallback"] = "We survive together, we fight together. Let's clear them out!",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.04",
                    ["phraseID"] = "warm.04",
                },
                {
                    ["fallback"] = "With you beside me, I'm not afraid. Let's take them down.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.05",
                    ["phraseID"] = "warm.05",
                },
                {
                    ["fallback"] = "Let's show them what real survivors are made of!",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.06",
                    ["phraseID"] = "warm.06",
                },
                {
                    ["fallback"] = "Right by your side, partner. We won't lose today.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.07",
                    ["phraseID"] = "warm.07",
                },
                {
                    ["fallback"] = "I trust us. Let's stand tall and fight.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.08",
                    ["phraseID"] = "warm.08",
                },
                {
                    ["fallback"] = "We've got this, friend. Watch my back and I'll watch yours.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.09",
                    ["phraseID"] = "warm.09",
                },
                {
                    ["fallback"] = "Stay close and hit hard! We'll celebrate after.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_brave.warm.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_brave.warm.10",
                    ["phraseID"] = "warm.10",
                },
            },
        },
    },
    ["semantic.interaction.scene.horde_reply_cautious"] = {
        ["canonicalConcept"] = "SEMANTIC_INTERACTION_SCENE_HORDE_REPLY_CAUTIOUS",
        ["contentOwner"] = "projecthoomans.dialogue_content.social_interaction",
        ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious",
        ["semanticTemplateID"] = "semantic.interaction.scene.horde_reply_cautious",
        ["styles"] = {
            ["guarded"] = {
                {
                    ["fallback"] = "Bad odds. Give them space.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.01",
                    ["phraseID"] = "guarded.01",
                },
                {
                    ["fallback"] = "Fighting that pack is suicide. Withdraw in formation.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.02",
                    ["phraseID"] = "guarded.02",
                },
                {
                    ["fallback"] = "Step back quietly. Do not alert the rear flank.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.03",
                    ["phraseID"] = "guarded.03",
                },
                {
                    ["fallback"] = "Keep your weapon raised, but reverse your footsteps.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.04",
                    ["phraseID"] = "guarded.04",
                },
                {
                    ["fallback"] = "We have zero tactical advantage. We fall back immediately.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.05",
                    ["phraseID"] = "guarded.05",
                },
                {
                    ["fallback"] = "Don't let adrenaline make you stupid. We withdraw.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.06",
                    ["phraseID"] = "guarded.06",
                },
                {
                    ["fallback"] = "Back away into the shadows. Let them wander past.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.07",
                    ["phraseID"] = "guarded.07",
                },
                {
                    ["fallback"] = "I refuse to be butchered in an open field. Retreat.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.08",
                    ["phraseID"] = "guarded.08",
                },
                {
                    ["fallback"] = "Keep low and retreat to the last secure building.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.09",
                    ["phraseID"] = "guarded.09",
                },
                {
                    ["fallback"] = "Orderly withdrawal. If anyone runs screaming, they're dead.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.guarded.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.guarded.10",
                    ["phraseID"] = "guarded.10",
                },
            },
            ["neutral"] = {
                {
                    ["fallback"] = "Too many. We should pull back.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.01",
                    ["phraseID"] = "neutral.01",
                },
                {
                    ["fallback"] = "The odds are terrible. Let's retreat and find another way.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.02",
                    ["phraseID"] = "neutral.02",
                },
                {
                    ["fallback"] = "Fighting here is a death sentence. Fall back.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.03",
                    ["phraseID"] = "neutral.03",
                },
                {
                    ["fallback"] = "We don't have the ammunition or stamina for this. Pull back.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.04",
                    ["phraseID"] = "neutral.04",
                },
                {
                    ["fallback"] = "Better to live and fight another day. Let's withdraw.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.05",
                    ["phraseID"] = "neutral.05",
                },
                {
                    ["fallback"] = "We're completely outmatched. Retreat orderly.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.06",
                    ["phraseID"] = "neutral.06",
                },
                {
                    ["fallback"] = "Back up slowly. Don't make sudden noises.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.07",
                    ["phraseID"] = "neutral.07",
                },
                {
                    ["fallback"] = "Let's slip away while they haven't locked onto us.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.08",
                    ["phraseID"] = "neutral.08",
                },
                {
                    ["fallback"] = "Too risky. We need to withdraw immediately.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.09",
                    ["phraseID"] = "neutral.09",
                },
                {
                    ["fallback"] = "I agree with retreating. Turn around and move quietly.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.neutral.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.neutral.10",
                    ["phraseID"] = "neutral.10",
                },
            },
            ["terse"] = {
                {
                    ["fallback"] = "Pull back.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.01",
                    ["phraseID"] = "terse.01",
                },
                {
                    ["fallback"] = "Too many. Run.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.02",
                    ["phraseID"] = "terse.02",
                },
                {
                    ["fallback"] = "Retreat.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.03",
                    ["phraseID"] = "terse.03",
                },
                {
                    ["fallback"] = "Fall back now.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.04",
                    ["phraseID"] = "terse.04",
                },
                {
                    ["fallback"] = "Bad odds. Leave.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.05",
                    ["phraseID"] = "terse.05",
                },
                {
                    ["fallback"] = "Out. Now.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.06",
                    ["phraseID"] = "terse.06",
                },
                {
                    ["fallback"] = "Back up.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.07",
                    ["phraseID"] = "terse.07",
                },
                {
                    ["fallback"] = "Not here. Move.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.08",
                    ["phraseID"] = "terse.08",
                },
                {
                    ["fallback"] = "Escape.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.09",
                    ["phraseID"] = "terse.09",
                },
                {
                    ["fallback"] = "Away.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.terse.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.terse.10",
                    ["phraseID"] = "terse.10",
                },
            },
            ["warm"] = {
                {
                    ["fallback"] = "I'd rather get us out of this alive. Pull back.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.01",
                    ["phraseID"] = "warm.01",
                },
                {
                    ["fallback"] = "I care too much about you to risk this. Let's retreat, friend.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.02",
                    ["phraseID"] = "warm.02",
                },
                {
                    ["fallback"] = "Please, let's fall back together. We don't have to die here.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.03",
                    ["phraseID"] = "warm.03",
                },
                {
                    ["fallback"] = "I need you alive, partner. Turn around, let's go.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.04",
                    ["phraseID"] = "warm.04",
                },
                {
                    ["fallback"] = "Let's save our strength for our people back home. Retreat.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.05",
                    ["phraseID"] = "warm.05",
                },
                {
                    ["fallback"] = "Take my hand if you need to, but we have to pull back now.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.06",
                    ["phraseID"] = "warm.06",
                },
                {
                    ["fallback"] = "There's no shame in living to fight tomorrow. Fall back with me.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.07",
                    ["phraseID"] = "warm.07",
                },
                {
                    ["fallback"] = "Let's back away gently, together. I've got you.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.08",
                    ["phraseID"] = "warm.08",
                },
                {
                    ["fallback"] = "We can find supplies elsewhere. Let's keep each other safe and run.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.09",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.09",
                    ["phraseID"] = "warm.09",
                },
                {
                    ["fallback"] = "I'm not leaving without you, so let's both back up right now.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_cautious.warm.10",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_cautious.warm.10",
                    ["phraseID"] = "warm.10",
                },
            },
        },
    },
    ["semantic.interaction.scene.horde_reply_steady"] = {
        ["canonicalConcept"] = "SEMANTIC_INTERACTION_SCENE_HORDE_REPLY_STEADY",
        ["contentOwner"] = "projecthoomans.dialogue_content.social_interaction",
        ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady",
        ["semanticTemplateID"] = "semantic.interaction.scene.horde_reply_steady",
        ["styles"] = {
            ["guarded"] = {
                {
                    ["fallback"] = "No rush. Hold position and watch the pressure.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.01",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.01",
                    ["phraseID"] = "guarded.01",
                },
                {
                    ["fallback"] = "Hold here. If you twitch, you draw the whole pack.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.02",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.02",
                    ["phraseID"] = "guarded.02",
                },
                {
                    ["fallback"] = "Stay rooted. Wait until their lead walkers pass.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.03",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.03",
                    ["phraseID"] = "guarded.03",
                },
                {
                    ["fallback"] = "Maintain silence and hold the corner.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.04",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.04",
                    ["phraseID"] = "guarded.04",
                },
                {
                    ["fallback"] = "Do not engage prematurely. Let the herd scatter.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.05",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.05",
                    ["phraseID"] = "guarded.05",
                },
                {
                    ["fallback"] = "Hold your breath if you have to, but don't move.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.06",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.06",
                    ["phraseID"] = "guarded.06",
                },
                {
                    ["fallback"] = "We wait for an exploitable mistake. Stay still.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.07",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.07",
                    ["phraseID"] = "guarded.07",
                },
                {
                    ["fallback"] = "Keep your weapon ready, but do not fire yet. Hold.",
                    ["id"] = "phrase.semantic.interaction.scene.horde_reply_steady.guarded.08",
                    ["key"] = "conversation.content.semantic.interaction.scene.horde_reply_steady.guarded.08",
                    ["phraseID"] = "guarded.08",
                },
                {
